    Ltac after_A sx ps XS mc CS ST CS2 ST2 :=
      match goal with MUx : munch [(bv_unsigned spw, bv_unsigned spw + 144)]%Z mc ?m2, WMx : wmono asegs mc ?m2, MIx : mem_inv asegs ?m2 |- _ =>
        assert (CS2 : cst sx ps XS m2) by (eapply (cst_frame sx ps XS mc m2); [exact CS| exact MUx| apply sub_lo; apply sub_144; lia| exact WMx| exact MIx]);
        assert (ST2 : stk asegs m2 lo (bv_unsigned spw)) by (eapply stk_frame; [exact ST| exact MUx| apply sub_144; lia| exact WMx])
      end.
